/** Persisted order record. */
export interface Order {
  id: string;
  total: number;
}

/** Data access contract used by {@link loadOrders}. */
export interface OrderStore {
  /**
   * Looks up many orders in a single round trip.
   *
   * @param ids - Order identifiers to resolve. Implementations may return matches in any order.
   * @returns Every order found; identifiers with no matching order are omitted.
   */
  findByIds(ids: readonly string[]): Promise<Order[]>;
}

const ORDER_NOT_FOUND_PREFIX = "order not found";

/**
 * Builds the error raised when an identifier has no matching order.
 *
 * @param id - Order identifier that did not resolve.
 * @returns An error whose message names the identifier.
 */
function orderNotFoundError(id: string): Error {
  return new Error(`${ORDER_NOT_FOUND_PREFIX}: ${id}`);
}

/**
 * Loads orders by identifier while preserving the requested order.
 *
 * @param store - Order data store.
